    unsigned long MemoryAllocated;                    // +0x400
    void**        MemoryAuditBuffer;                  // +0x404
    void*         Heap;                               // +0x408
    unsigned long NoAllocations;                      // +0x40c
    unsigned long NoAllocators;                       // +0x410
    unsigned char _rest[0x49c - 0x414];
