void* __fastcall CMemoryAllocator::AllocateAligned(unsigned long size, long alignment)
{
    void* block = Allocate(size + alignment + 3, 0);
    void** aligned = (void**)(((unsigned long)block + alignment + 3) & ~(alignment - 1));
    aligned[-1] = block;
    return aligned;
}

